class Solution {
    public int maxArea(int[] height) {
        int left = 0, right = height.length -1 ;
        int max_area = 0;

        while(left < right){
            int h = Math.min(height[left], height[right]);
            int width = right - left;
            max_area = Math.max(max_area, h * width);

            if(height[left] < height[right]){
                left++;
            }else{
                right--;
            }
        }
        return max_area;
    }
}

class Solution {
public:
    string intToRoman(int num) {
        vector<pair<int, string>> itor ={{1000, "M"}, {900, "CM"}, {500, "D"}, {400, "CD"}, {100, "C"},
            {90, "XC"},  {50, "L"},   {40, "XL"}, {10, "X"},   {9, "IX"},
            {5, "V"},    {4, "IV"},   {1, "I"}};

        string ans = "";

        for(auto const &[value, symbol] : itor){
            if(num == 0) break;

            while(num >= value){
                ans += symbol;
                num -= value;
            }
        }
        return ans;
    }
};

class Solution {
    public int romanToInt(String s) {
        int result = 0;
        Map<Character, Integer> roman = new HashMap<>();

        roman.put('I', 1);
        roman.put('V', 5);
        roman.put('X', 10);
        roman.put('L', 50);
        roman.put('C', 100);
        roman.put('D', 500);
        roman.put('M', 1000);

        for(int i = 0; i < s.length()-1; i++){
            if(roman.get(s.charAt(i)) < roman.get(s.charAt(i+1))){
                result -= roman.get(s.charAt(i));
            }else{
                result += roman.get(s.charAt(i));
            }
        }

        return result + roman.get(s.charAt(s.length()-1));
    }
}

class Solution {
public:
    vector<vector<int>> threeSum(vector<int>& nums) {
        vector<vector<int>> result;
        sort(nums.begin(), nums.end());

        for(int i = 0; i < nums.size(); i++){
            //check if duplicate
            if(i > 0 && nums[i] == nums[i-1]){
                continue;
            }

            int j = i+1;
            int k = nums.size()-1;

            while(j < k){
                int total = nums[i] + nums[j] + nums[k];

                if(total > 0){
                    k--;
                }else if(total < 0){
                    j++;
                }else{
                    result.push_back({nums[i], nums[j], nums[k]});
                    j++;

                    while(nums[j] == nums[j-1] && j < k){
                        j++;
                    }
                }
            }
        }
        return result;
    }
};

class Solution {
    public List<List<Integer>> threeSum(int[] nums) {
        List<List<Integer>> result =  new ArrayList<>();
        Arrays.sort(nums);
        int n = nums.length;

        for(int i = 0; i < n - 2; i++){
            if(i > 0 && nums[i] == nums[i-1]){
                continue;
            }

            int j = i+1;
            int k = n-1;

            while(j < k){
                int sum = nums[i] + nums[j] + nums[k];

                if(sum < 0){
                    j = j+1;
                }

                if (sum > 0){
                    k = k-1;
                }

                if (sum == 0){
                    result.add(Arrays.asList(nums[i], nums[j],nums[k]));

                    j++;
                    k--;

                    while(j < k && nums[j] == nums[j-1]){
                        j++;
                    }

                    while(k > j && nums[k] == nums[k+1]){
                        k--;
                    }
                }
            }
        }
        return result;
    }
}

class Solution {
public:
    int threeSumClosest(vector<int>& nums, int target) {
        sort(nums.begin(), nums.end());
        int closest = INT_MAX / 3;

        for(int i = 0; i < nums.size()-2; i++){
            int left = i + 1, right = nums.size()-1;
            while(left < right){
                int curr = nums[i] + nums[left] + nums[right];
                if(abs(curr - target) < abs(closest - target)){
                    closest = curr;
                }

                if(curr < target){
                    left++;
                }else if(curr > target){
                    right--;
                }else{
                    return curr;
                }
            }
        }

        return closest;
    }
};

class Solution {
public:
    vector<string> letterCombinations(string digits) {
        vector<string> res;

        if(digits.empty()){
            return res;
        }

        unordered_map<char, string> digitToLetters ={
            {'2', "abc"}, {'3', "def"},
            {'4', "ghi"}, {'5', "jkl"},
            {'6', "mno"}, {'7', "pqrs"},
            {'8', "tuv"}, {'9', "wxyz"}
        };

        backtrack(digits, 0, "", res, digitToLetters);

        return res;
    }

    void backtrack(const string& digits, int idx, string combo, vector<string>& res, const unordered_map<char, string>& digitToLetters){
        if(idx == digits.length()){
            res.push_back(combo);
            return;
        }

        string letters = digitToLetters.at(digits[idx]);
        for(char letter:letters){
            backtrack(digits, idx+1, combo + letter, res, digitToLetters);
        }
    }
};

class Solution {
    public List<List<Integer>> fourSum(int[] nums, int target) {
        List<List<Integer>> result = new ArrayList<>();
        Arrays.sort(nums);
        int n = nums.length;

        for(int i = 0; i <= n-4; i++){
            if(i != 0 && nums[i] == nums[i-1]){
                continue;
            }
            for(int j = i+1; j <= n-3; j++){
                if(j != i+1 && nums[j] == nums[j-1]){
                    continue;
                }

                int left = j+1;
                int right = n-1;

                while(left < right){
                    long sum = (long) nums[i] + nums[j] + nums[left] + nums[right];

                    if(sum > target){
                        right--;
                    }else if(sum < target){
                        left++;
                    }else{
                        result.add(Arrays.asList(nums[i], nums[j], nums[left], nums[right]));

                        left++;
                        right--;

                        while(right > left && nums[right] == nums[right+1]){
                            right--;
                        }

                        while(left < right && nums[left] == nums[left-1]){
                            left++;
                        }
                    }
                }
            }
        }
        return result;
    }
}

class Solution:
    def isValid(self, s: str) -> bool:
        stack = []
        mapping = {")" : "(", "}" : "{", "]":"["}

        for char in s:
            if char in mapping.values():
                stack.append(char)
            elif char in mapping.keys():
                if not stack or mapping[char] != stack.pop():
                    return False

        return not stack

class Solution {
    public boolean isValid(String s) {
        Stack<Character> stack = new Stack<>();
        for(char c : s.toCharArray()){
            if(c == '(' || c == '{' || c == '['){
                stack.push(c);
            }else{
                if(stack.isEmpty()){
                    return false;
                }
                char top = stack.pop();
                if(c == ')' && top != '('){
                    return false;
                }
                if(c == '}' && top != '{'){
                    return false;
                }
                if(c == ']' && top != '['){
                    return false;
                }
            }
        }

        return stack.isEmpty();
    }
}

