#     def __init__(self, val=0, next=None):
#         self.val = val
#         self.next = next
class Solution:
    def mergeTwoLists(self, list1: Optional[ListNode], list2: Optional[ListNode]) -> Optional[ListNode]:
        current = dummy = ListNode()

        while list1 and list2:
            if list1.val > list2.val:
                current.next = list2
                list2 = list2.next
            else:
                current.next = list1
                list1 = list1.next

            current = current.next

        if list1:
            current.next = list1
        else:
            current.next = list2

        return dummy.next

class Solution {
public:
    void generate(int openC, int closeC, string curr, vector<string>& res, int n){
        //Check if all open and close used
        if(curr.length() == 2 * n){
            res.push_back(curr);
            return;
        }
        //Check if all open count used
        if(openC < n){
            generate(openC + 1, closeC, curr + "(", res, n);
        }
        //Check if all close count used
        if(closeC < openC){
            generate(openC, closeC + 1, curr + ")", res, n);
        }
    }

    vector<string> generateParenthesis(int n) {
        vector<string> res;
        generate(0, 0, "", res, n);
        return res;
    }
};

