class Solution {
public:
    vector<vector<int>> subsets(vector<int>& nums) {
        vector<vector<int>> result;
        vector<int> subset;

        backtrack(nums, subset, result, 0);

        return result;
    }

    void backtrack(vector<int>& nums, vector<int>& subset, vector<vector<int>>& result, int idx){
        if(nums.size() == idx){
            result.push_back(subset);
            return;
        }

        subset.push_back(nums[idx]);
        backtrack(nums, subset, result, idx+1);
        subset.pop_back();
        backtrack(nums, subset, result, idx+1);
    }
};

class Solution {
public:
    void merge(vector<int>& nums1, int m, vector<int>& nums2, int n) {
        int size = m + n - 1;
        int midx = m -1;
        int nidx = n-1;

        while(nidx >= 0){
            if(midx >= 0 && nums1[midx] > nums2[nidx]){
                nums1[size] = nums1[midx];
                midx--;
            }else{
                nums1[size] = nums2[nidx];
                nidx--;
            }
            size--;
        }
    }
};

class Solution {
public:
    vector<vector<int>> subsetsWithDup(vector<int>& nums) {
        vector<vector<int>> result;
        vector<int> combo;

        sort(nums.begin(), nums.end());
        backtrack(nums, result, combo, 0);

        return result;
    }

    void backtrack(vector<int>& nums, vector<vector<int>>& result, vector<int>& combo, int idx){
        result.push_back(combo);

        for(int i = idx; i < nums.size(); i++){
            if(i > idx && nums[i] == nums[i-1]) continue;

            combo.push_back(nums[i]);
            backtrack(nums, result, combo, i+1);
            combo.pop_back();
        }
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> result;
        inorder(root, result);
        return result;
    }

    void inorder(TreeNode *root, vector<int>& result){
        if(!root) return;

        inorder(root->left, result);
        result.push_back(root->val);
        inorder(root->right, result);
    }
};

class Solution {
public:
    int numTrees(int n) {
        vector<int> dp(n+1, 0);
        dp[0] = dp[1] = 1;

        for(int i = 2; i <= n; i++){
            for(int j = 1; j <= i; j++){
                int left = j - 1;
                int right = i - j;
                dp[i] += dp[left] * dp[right];
            }
        }

        return dp[n];
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    bool isSameTree(TreeNode* p, TreeNode* q) {
        if(!p && !q){
            return true;
        }

        if(p==NULL || q==NULL){
            return false;
        }

        if(p->val == q->val){
            return isSameTree(p->left, q->left) && isSameTree(p->right, q->right);
        }

        return false;

    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    bool isSymmetric(TreeNode* left, TreeNode* right){
        if(!left && !right) return true;
        if(!left || !right) return false;
        return (left->val == right->val) && isSymmetric(left->left, right->right) && isSymmetric(left->right, right->left);
    }

    bool isSymmetric(TreeNode* root) {
        if(root == NULL){
            return true;
        }
        return isSymmetric(root->left, root->right);
    }
};

