        ugly[0] = 1;

        int i2 = 0, i3 = 0, i5 = 0;
        int next2 = 2, next3 = 3, next5 = 5;

        for(int i = 1; i < n; i++){
            int nextUgly = std::min({next2, next3, next5});
            ugly[i] = nextUgly;

            if(nextUgly == next2) next2 = 2 * ugly[++i2];
            if(nextUgly == next3) next3 = 3 * ugly[++i3];
            if(nextUgly == next5) next5 = 5 * ugly[++i5];
        }

        return ugly[n-1];
    }
};

