 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    int findBottomLeftValue(TreeNode* root) {
        if(!root) return -1;

        queue<TreeNode*> q;
        q.push(root);
        int result = root->val;

        while(!q.empty()){
            TreeNode* node = q.front();
            q.pop();

            if(node->right) q.push(node->right);
            if(node->left) q.push(node->left);

            result = node->val;
        }

        return result;
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    vector<int> largestValues(TreeNode* root) {
        vector<int> result;
        if(!root) return result;

        queue<TreeNode*> q;
        q.push(root);

        while(!q.empty()){
            int maxVal = INT_MIN;
            int size = q.size();

            for(int i = 0; i < size; i++){
                TreeNode* node = q.front();
                q.pop();

                maxVal = max(maxVal, node->val);
                if(node->left) q.push(node->left);
                if(node->right) q.push(node->right);
            }

            result.push_back(maxVal);
        }

        return result;
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    int getMinimumDifference(TreeNode* root) {
        int minDiff = INT_MAX;
        int prev = -1;
        inorderTraversal(root, prev, minDiff);
        return minDiff;
    }

    void inorderTraversal(TreeNode* root, int& prev, int& minDiff){
        if(!root) return;

        inorderTraversal(root->left, prev, minDiff);

        if(prev != -1){
            minDiff = min(minDiff, root->val - prev);
        }

        prev = root->val;

        inorderTraversal(root->right, prev, minDiff);
    }
};

class Solution {
public:
    int findPairs(vector<int>& nums, int k) {
        if(k < 0) return 0;

        unordered_map<int, int> count;
        int result = 0;

        for(int num : nums){
            count[num]++;
        }

        for(auto& entry:count){
            int num = entry.first;

            //num - (num + k) = k
            //So, if find (num + k) inside the map, it will be a unique pair
            if(k > 0 && count.find(num + k)!= count.end()){
                result++;
            }

            //This situation is when only have 2 same value of num then k will be zero
            //So, if the freq of the num now, it will be counted as a unique pair also
            if(k == 0 && entry.second > 1){
                result++;
            }
        }
        return result;
    }
};

