class Solution {
public:
    vector<int> intersection(vector<vector<int>>& nums) {
        int size = nums.size();
        unordered_map<int, int>freq;
        vector<int> res;

        for(size_t i = 0; i < nums.size(); i++){
            for(size_t j = 0; j < nums[i].size(); j++){
                freq[nums[i][j]]++;
            }
        }

        for(const auto [key, value] : freq){
            if(value == size){
                res.push_back(key);
            }
        }

        sort(res.begin(), res.end());

        return res;
    }
};

class Solution:
    def waysToSplitArray(self, nums: List[int]) -> int:
        total = sum(nums)
        left_sum = 0
        cnt = 0

        for i in range(len(nums)-1):
            left_sum += nums[i]
            right_sum = total - left_sum

            if left_sum >= right_sum:
                cnt += 1

        return cnt

class Solution {
public:
    int rearrangeCharacters(string s, string target) {
        unordered_map<char, int>freq_s, freq;

        for(char c : s){
            freq_s[c]++;
        }

        for(char t : target){
            freq[t]++;
        }

        int minCopies = INT_MAX;
        for(const auto& pair : freq){
            char letter = pair.first;
            int required = pair.second;

            if(freq_s[letter] == 0) return 0;

            minCopies = min(minCopies, freq_s[letter]/required);
        }
        return minCopies;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, long long k) {
        int start = 0;
        long long sum = 0;
        long long count = 0;

        for(int end = 0; end < nums.size(); end++){
            sum += nums[end];

            while(sum * (end-start+1) >= k){
                sum -= nums[start];
                start++;
            }

            count += end-start+1;
        }

        return count;
    }
};

class Solution {
public:
    vector<int> numberOfPairs(vector<int>& nums) {
        int count = 0;
        unordered_map<int, int>freq;

        for(int num : nums){
            freq[num]++;

            if(freq[num] % 2 == 0){
                count++;
            }
        }

        int left = nums.size() - (count * 2);

        return {count, left};
    }
};

class Solution {
public:
    char repeatedCharacter(string s) {
        unordered_map<char, int> first;

        for(char c : s){
            first[c]++;

            if(first[c] == 2){
                return c;
            }
        }

        return ' ';
    }
};

class Solution {
public:
    string removeStars(string s) {
        string letter = "";
        int i = 0;

        while(i < s.size()){
            if(s[i] == '*'){
                letter.pop_back();
            }else{
                letter += s[i];
            }
            i++;
        }      
        return letter;
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    TreeNode* reverseOddLevels(TreeNode* root) {
        if(!root) return nullptr;

        queue<TreeNode*> q;
        q.push(root);
        int level = 0;

        while(!q.empty()){
            int size = q.size();
            vector<TreeNode*> nodes;

            for(int i = 0; i < size; i++){
                TreeNode* node = q.front();
                q.pop();
                nodes.push_back(node);

                if(node->left) q.push(node->left);
                if(node->right) q.push(node->right);
            }

            if(level % 2 == 1){
                int left = 0, right = nodes.size() - 1;
                while(left < right){
                    swap(nodes[left]->val, nodes[right]->val);
                    left++;
                    right--;
                }
            }
            level++;
        }
        return root;
    }
};

class Solution {
public:
    int distinctAverages(vector<int>& nums) {
        unordered_set<double> res;

        sort(nums.begin(), nums.end());

        while(!nums.empty()){
            int min = nums.front();
            int max = nums.back();
            res.insert((max + min)/2.0);

            nums.erase(nums.begin());
            nums.pop_back();
        }

        return res.size();
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    vector<int> sortedval;

    void inorder(TreeNode* node){
        if(!node) return;

        inorder(node->left);
        sortedval.push_back(node->val);
        inorder(node->right);
    }

    vector<vector<int>> closestNodes(TreeNode* root, vector<int>& queries) {
        inorder(root);

        vector<vector<int>> ans;

        for(int q : queries){
            //lower_bound used to get the val just after the target.
            auto it = lower_bound(sortedval.begin(), sortedval.end(), q);

            int mini = (it == sortedval.begin()) ? -1 : *(prev(it));
            if( it!=sortedval.end()&& *it == q ) mini = q;
            int max = (it==sortedval.end())? -1 : *it;

            ans.push_back({mini, max});
        }
        return ans;
    }
};

class Solution {
public:
    int deleteGreatestValue(vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();

        for(int i = 0; i < m; i++){
            sort(grid[i].begin(), grid[i].end());
        }

        int result = 0;

        for(int i = n-1; i >= 0; i--){
            int maxVal = 0;
            for(int j = 0; j < m; j++){
                maxVal = max(maxVal, grid[j][i]);
            }
            result += maxVal;
        }

        return result;
    }
};

class Solution {
public:
    int maximumCount(vector<int>& nums) {
        int neg_count = binarySearch(nums, 0);
        int pos_count = nums.size()-binarySearch(nums, 1);

        return max(neg_count, pos_count);
    }

    int binarySearch(vector<int>& nums, int target){
        int left = 0, right = nums.size()-1, result = nums.size();

        while(left<=right){
            int mid = (left + right) / 2;
            if(nums[mid] < target){
                left = mid+1;
            }else{
                result = mid;
                right = mid-1;
            }
        }

        return result;
    }
};

class Solution {
public:
    int getCommon(vector<int>& nums1, vector<int>& nums2) {
        int i = 0, j = 0;
        int common = -1;

        while(i < nums1.size() && j < nums2.size()){
            if(nums1[i] == nums2[j]){
                common = nums1[i];
                break;
            }else if(nums1[i] < nums2[j]){
                i++;
            }else{
                j++;
            }
        }

        return common;
    }
};

class Solution:
    def vowelStrings(self, words: List[str], queries: List[List[int]]) -> List[int]:
        #get the list length
        n = len(words)
        #create a vowel dictionary
        vowel = {'a', 'e', 'i', 'o', 'u'}
        #create a prefix
        Prefix = [0] * (n+1)

        #for loop
        for i in range(n):
            Prefix[i+1] = Prefix[i]
            if words[i][0] in vowel and words[i][-1] in vowel:
                Prefix[i+1] += 1

        ANS = []
        for query in queries:
            ANS.append(Prefix[query[1]+1]- Prefix[query[0]])

        return ANS

