class Solution {
public:
    int countCompleteSubarrays(vector<int>& nums) {
        int n = nums.size();
        int count = 0;
        unordered_set<int> distinct(nums.begin(), nums.end());
        int distinctSize = distinct.size();

        for(int i = 0; i < n; i++){
            unordered_set<int> current;
            for(int j = i; j < n; j++){
                current.insert(nums[j]);

                if(current.size() == distinctSize){
                    count++;
                }
            }
        }

        return count;
    }
};

class Solution {
public:
    int countPairs(vector<int>& nums, int target) {
        sort(nums.begin(), nums.end());
        int left = 0, right = nums.size()-1, count = 0;

        while(left<=right){
            if(nums[right] + nums[left] < target){
                count += (right-left);
                left++;
            }else{
                right--;
            }
        }

        return count;
    }
};

class Solution {
public:
    int minLengthAfterRemovals(vector<int>& nums) {
        int n = nums.size();
        int mid = n / 2;
        int i = 0, j = mid;
        int pairs = 0;

        while(i < mid && j < n){
            if(nums[i] < nums[j]){
                pairs++;
                i++;
            }
            j++;
        }

        return n-2*pairs;
    }
};

class Solution {
public:
    vector<int> numberGame(vector<int>& nums) {
        priority_queue<int, vector<int>, greater<int>> pq(nums.begin(), nums.end());
        vector<int> result;

        while(pq.size() > 1){
            int first = pq.top();
            pq.pop();
            int sec = pq.top();
            pq.pop();

            result.push_back(sec);
            result.push_back(first);
        }

        return result;
    }
};

class Solution:
    def countPrefixSuffixPairs(self, words: List[str]) -> int:
        n = len(words)
        cnt = 0

        for i in range(n):
            for j in range(i+1, n):
                str1 = words[i]
                str2 = words[j]

                #str1 cannot have a longer length than str2
                if len(str1) > len(str2):
                    continue

                if str2.startswith(str1) and str2.endswith(str1):
                    cnt += 1

        return cnt

class Solution {
public:
    int maximumLengthSubstring(string s) {
        int maxCount = 0;
        int left = 0;
        unordered_map<char, int>freq;

        for(int right = 0; right < s.length(); right++){
            freq[s[right]]++;

            while(freq[s[right]] > 2){
               freq[s[left]]--;
               left++;
            }

            maxCount = max(maxCount, right-left+1);
        }

        return maxCount;
    }
};

class Solution {
public:
    string clearDigits(string s) {
        string result;
        stack<char> st;

        for(char c : s){
            if(isdigit(c)){
                if(!st.empty() && !isdigit(st.top())){
                    st.pop();
                }
            }else{
                st.push(c);
            }
        }

        while(!st.empty()){
            result = st.top() + result;
            st.pop();
        }
        return result;
    }
};

class Solution {
public:
    int countKConstraintSubstrings(string s, int k) {
        int left = 0, count0 = 0, count1 = 0, result = 0;

        for(int right = 0; right < s.length(); right++){
            if(s[right] == '0') count0++;
            else count1++;

            while(count0 > k && count1 > k){
                if(s[left] == '0' ) count0--;
                else count1--;
                left++;
            }

            result += (right-left+1);
        }

        return result;
    }
};

class Solution {
public:
    int countSubarrays(vector<int>& nums) {
        int count = 0;

        for(int i = 0; i < nums.size() - 2; i++){
            int result = nums[i] + nums[i+2];

            if(nums[i+1] == result * 2){
                count += 1;
            }
        }

        return count;
    }
};

class Solution {
    public int countCommas(int n) {
        int digits = String.valueOf(n).length();
        int total = 0;
        int count = 0;
        int commas = 0;

        for(int i = 1; i <= digits; i++){
            int low = (int) Math.pow(10, i-1);
            int high = (int) Math.pow(10, i) -1;

            if(n >= high){
                count = high-low+1;
            }else{
                count = n-low+1;
            }

            commas = (i-1)/3;
            total += commas * count;
        }

        return total;
    }
}

class Solution {
    public int firstStableIndex(int[] nums, int k) {
        int n = nums.length;
        int[] suf = new int[100];
        suf[n-1] = nums[n-1];
        int max = 0;

        for(int i = n-2; i >=0; i--)
            suf[i] = Math.min(suf[i+1], nums[i]);

        for(int i = 0; i < n; i++){
            max = Math.max(max, nums[i]);
            if(max - suf[i] <= k){
                return i;
            }
        }

        return -1;
    }
}
